/**
 * The inbound-email Worker (#1217).
 *
 * Cloudflare Email Routing hands every message sent to a store address (orders@, support@ …) to
 * this Worker's `email()` handler. It asks the application which vendor owns the address and where
 * the store's real mailbox is, then forwards the message there.
 *
 * WHY A SEPARATE WORKER. `.open-next/worker.js` is generated by `opennextjs-cloudflare build` and
 * exports only `fetch`, so there is nowhere on the application Worker to attach an `email` handler —
 * the same reason `workers/scheduler` exists. Like the scheduler it holds no database and no vendor
 * knowledge: it calls `/api/inbound-email/resolve` with a shared secret.
 *
 * NOTHING IS LOST. On any failure other than a definite "unknown address" (404) — a network error,
 * a 5xx, a misconfigured token — the message goes to INBOUND_FALLBACK_FORWARD instead, so an
 * application outage never drops a customer's email.
 *
 * NOTHING PERSONAL IS LOGGED. The one log line carries the vendor id, purpose, order flag and order
 * number — never the sender, the subject or the body (R22). `#1390` attaches the WhatsApp alert at
 * that point.
 */

export interface Env {
  /** Origin of the application Worker, e.g. `https://aheed-staging.merqify.com`. */
  APP_BASE_URL: string;
  /** Shared secret proving to the application that a request came from here. */
  INBOUND_EMAIL_TOKEN: string;
  /** A verified Email Routing destination that receives mail whenever resolving fails. */
  INBOUND_FALLBACK_FORWARD: string;
}

/** The part of Cloudflare's ForwardableEmailMessage this Worker uses, so tests can fake it. */
export interface InboundMessage {
  readonly to: string;
  readonly headers: Headers;
  forward(rcptTo: string, headers?: Headers): Promise<unknown>;
  setReject(reason: string): void;
}

interface Resolution {
  forwardTo: string;
  vendorId: string;
  purpose: string;
  orderRelated: boolean;
  orderNumber: string | null;
}

export const RESOLVE_PATH = "/api/inbound-email/resolve";

async function forwardToFallback(message: InboundMessage, env: Env, why: string): Promise<void> {
  console.error(`inbound-email resolve failed (${why}); forwarding to the fallback mailbox`);
  await message.forward(env.INBOUND_FALLBACK_FORWARD);
}

export async function handleInboundEmail(message: InboundMessage, env: Env): Promise<void> {
  let response: Response;
  try {
    response = await fetch(new URL(RESOLVE_PATH, env.APP_BASE_URL), {
      method: "POST",
      headers: { "content-type": "application/json", "x-inbound-token": env.INBOUND_EMAIL_TOKEN },
      body: JSON.stringify({ to: message.to, subject: message.headers.get("subject") ?? "" }),
    });
  } catch {
    await forwardToFallback(message, env, "network error");
    return;
  }

  if (response.status === 404) {
    message.setReject("Unknown recipient");
    console.log("inbound-email rejected: no store owns this address");
    return;
  }

  if (!response.ok) {
    await forwardToFallback(message, env, `status ${response.status}`);
    return;
  }

  let resolution: Resolution;
  try {
    resolution = (await response.json()) as Resolution;
  } catch {
    await forwardToFallback(message, env, "unreadable response");
    return;
  }

  await message.forward(resolution.forwardTo);
  console.log(
    `inbound-email vendorId=${resolution.vendorId} purpose=${resolution.purpose} ` +
      `orderRelated=${resolution.orderRelated} orderNumber=${resolution.orderNumber ?? "none"}`,
  );
}

const inboundEmailWorker = {
  async email(message: InboundMessage, env: Env, _ctx: ExecutionContext): Promise<void> {
    await handleInboundEmail(message, env);
  },
};

export default inboundEmailWorker;
